// Cloudflare Worker entry: the OpenNext-built Next.js app, plus a Cron Trigger
// that flushes the email outbox every minute through the app's internal route.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";

type Env = { APP_ORIGIN?: string };
type Ctx = { waitUntil(promise: Promise<unknown>): void };

// Random per-isolate token. The route accepts it only from this same isolate,
// because the request below is handed to the app directly, not over the network.
const cronToken = () => {
  const g = globalThis as { __watchguyCronToken?: string };
  if (!g.__watchguyCronToken) {
    const bytes = crypto.getRandomValues(new Uint8Array(32));
    g.__watchguyCronToken = Array.from(bytes, (b) =>
      b.toString(16).padStart(2, "0"),
    ).join("");
  }
  return g.__watchguyCronToken;
};

export default {
  fetch: handler.fetch,
  // Awaited directly: handing this request to ctx.waitUntil never completes.
  async scheduled(_controller: unknown, env: Env, ctx: Ctx) {
    const origin = (env.APP_ORIGIN || "https://watchguy.internal").replace(
      /\/$/,
      "",
    );
    const request = new Request(origin + "/api/internal/mail-flush", {
      method: "POST",
      headers: { authorization: "Bearer " + cronToken() },
    });
    const res: Response = await handler.fetch(request, env, ctx);
    if (!res.ok) console.error("mail flush", res.status, await res.text());
  },
};
